import scala.collection.mutable.ListBuffer

object Main {
  def solveNQueens(n: Int): List[List[String]] = {
    def isSafe(board: Array[Int], row: Int, col: Int): Boolean = {
      // التحقق من عدم تعارض العمود أو الأقطار
      for (r <- 0 until row) {
        if (board(r) == col || math.abs(board(r) - col) == row - r) return false
      }
      true
    }

    def backtrack(row: Int, board: Array[Int], result: ListBuffer[List[String]]): Unit = {
      if (row == n) {
        // بناء تمثيل نصي للوحة
        result += board.map(c => (0 until n).map(i => if (i == c) 'Q' else '.').mkString).toList
      } else {
        for (col <- 0 until n) {
          if (isSafe(board, row, col)) {
            board(row) = col
            backtrack(row + 1, board, result)
          }
        }
      }
    }

    val result = ListBuffer[List[String]]()
    backtrack(0, new Array[Int](n), result)
    result.toList
  }

  def main(args: Array[String]): Unit = {
    val solutions = solveNQueens(4)
    println(s"Number of solutions: ${solutions.length}")
    solutions.foreach { sol =>
      println(sol.mkString(","))
      println("---")
    }
  }
}

