import scala.collection.mutable

object Main {
  def bfs(graph: Map[Int, List[Int]], start: Int): List[Int] = {
    val visited = mutable.Set[Int]()
    val queue = mutable.Queue[Int]()
    val order = mutable.ListBuffer[Int]()

    queue.enqueue(start)
    visited.add(start)

    while (queue.nonEmpty) {
      val node = queue.dequeue()
      order += node
      // زيارة الجيران غير المكتشفين
      for (neighbor <- graph.getOrElse(node, Nil) if !visited.contains(neighbor)) {
        visited.add(neighbor)
        queue.enqueue(neighbor)
      }
    }
    order.toList
  }

  def main(args: Array[String]): Unit = {
    val graph = Map(
      0 -> List(1, 2),
      1 -> List(0, 3, 4),
      2 -> List(0, 5),
      3 -> List(1),
      4 -> List(1, 5),
      5 -> List(2, 4)
    )
    println(bfs(graph, 0).mkString(" "))
  }
}

import scala.collection.mutable.ArrayBuffer

object Main {
  def main(args: Array[String]): Unit = {
    val heap = ArrayBuffer.empty[Int]
    // إدراج عنصر مع الحفاظ على خاصية الكومة
    def insert(x: Int): Unit = {
      heap += x
      var i = heap.length - 1
      while (i > 0 && heap((i - 1) / 2) > heap(i)) {
        val tmp = heap((i - 1) / 2)
        heap((i - 1) / 2) = heap(i)
        heap(i) = tmp
        i = (i - 1) / 2
      }
    }
    // استخراج العنصر الأصغر
    def extractMin(): Int = {
      val min = heap(0)
      heap(0) = heap.last
      heap.remove(heap.length - 1)
      var i = 0
      var done = false
      while (!done) {
        val left = 2 * i + 1
        val right = 2 * i + 2
        var smallest = i
        if (left < heap.length && heap(left) < heap(smallest)) smallest = left
        if (right < heap.length && heap(right) < heap(smallest)) smallest = right
        if (smallest != i) {
          val tmp = heap(i)
          heap(i) = heap(smallest)
          heap(smallest) = tmp
          i = smallest
        } else done = true
      }
      min
    }
    // نضيف عناصر ثم نستخرجها
    insert(5); insert(3); insert(8); insert(1)
    println(extractMin()) // 1
    println(extractMin()) // 3
  }
}

object Main {
  def binarySearch(arr: Array[Int], target: Int): Int = {
    var low = 0
    var high = arr.length - 1
    while (low <= high) {
      val mid = low + (high - low) / 2 // تجنب تجاوز النطاق
      if (arr(mid) == target) return mid
      else if (arr(mid) < target) low = mid + 1
      else high = mid - 1
    }
    -1
  }

  def main(args: Array[String]): Unit = {
    val arr = Array(2, 5, 8, 12, 16, 23, 38, 56, 72, 91)
    val targets = Array(5, 23, 100)
    for (t <- targets) {
      val idx = binarySearch(arr, t)
      println(s"$t found at index $idx")
    }
  }
}

object Main {
  def main(args: Array[String]): Unit = {
    // عقدة الشجرة
    class Node(val key: Int, var left: Node = null, var right: Node = null)

    // إدراج قيمة في شجرة البحث الثنائية
    def insert(root: Node, key: Int): Node = {
      if (root == null) new Node(key)
      else if (key < root.key) { root.left = insert(root.left, key); root }
      else if (key > root.key) { root.right = insert(root.right, key); root }
      else root // تجاهل المكرر
    }

    // اجتياز بالترتيب: يسار، جذر، يمين
    def inorder(node: Node): Unit = {
      if (node != null) {
        inorder(node.left)
        print(node.key + " ")
        inorder(node.right)
      }
    }

    // بناء الشجرة من مصفوفة
    val values = Array(50, 30, 70, 20, 40, 60, 80)
    var root: Node = null
    for (v <- values) root = insert(root, v)

    inorder(root)
    println()
  }
}

