object Main {
  // tailrec تضمن تحويل العودية إلى حلقة لتجنب تجاوز المكدس
  @tailrec
  def factorial(n: Int, acc: BigInt = 1): BigInt = {
    if (n <= 1) acc
    else factorial(n - 1, acc * n)
  }

