object Main {
  def knapsack(capacity: Int, weights: Array[Int], values: Array[Int]): Int = {
    val n = weights.length
    val dp = Array.ofDim[Int](n + 1, capacity + 1)
    for (i <- 1 to n) {
      for (w <- 1 to capacity) {
        if (weights(i - 1) <= w) {
          dp(i)(w) = math.max(dp(i - 1)(w), values(i - 1) + dp(i - 1)(w - weights(i - 1)))
        } else {
          dp(i)(w) = dp(i - 1)(w)
        }
      }
    }
    dp(n)(capacity)
  }

  def main(args: Array[String]): Unit = {
    val weights = Array(2, 3, 4, 5)
    val values = Array(3, 4, 5, 6)
    val capacity = 5
    println(s"Max value: ${knapsack(capacity, weights, values)}")
  }
}

