object Main {
  def main(args: Array[String]): Unit = {
    // عقدة القائمة المترابطة
    class Node(val data: Int, var next: Node = null)

    // بناء قائمة: 1 -> 2 -> 3 -> 4 -> 5
    val head = new Node(1, new Node(2, new Node(3, new Node(4, new Node(5)))))

    // عكس القائمة بتغيير اتجاه الروابط
    def reverse(head: Node): Node = {
      var prev: Node = null
      var curr = head
      while (curr != null) {
        val next = curr.next // نحفظ العقدة التالية قبل كسر الرابط
        curr.next = prev     // نقلب الرابط
        prev = curr
        curr = next
      }
      prev // الرأس الجديد
    }

    // طباعة القائمة المعكوسة
    def printList(node: Node): Unit = {
      var curr = node
      while (curr != null) {
        print(curr.data + " ")
        curr = curr.next
      }
      println()
    }

    printList(reverse(head))
  }
}

