object Main {
  def mergeSort(arr: Array[Int]): Int = {
    def merge(l: Int, m: Int, r: Int): Int = {
      val left = arr.slice(l, m + 1)
      val right = arr.slice(m + 1, r + 1)
      var i = 0; var j = 0; var k = l; var inv = 0
      while (i < left.length && j < right.length) {
        if (left(i) <= right(j)) { arr(k) = left(i); i += 1 }
        else { arr(k) = right(j); inv += left.length - i; j += 1 }
        k += 1
      }
      while (i < left.length) { arr(k) = left(i); i += 1; k += 1 }
      while (j < right.length) { arr(k) = right(j); j += 1; k += 1 }
      inv
    }

    def sort(l: Int, r: Int): Int = {
      if (l >= r) 0
      else {
        val m = l + (r - l) / 2
        sort(l, m) + sort(m + 1, r) + merge(l, m, r)
      }
    }

    sort(0, arr.length - 1)
  }

  def main(args: Array[String]): Unit = {
    val arr = Array(1, 20, 6, 4, 5)
    val inv = mergeSort(arr)
    println(arr.mkString(" "))
    println(s"Inversions: $inv")
  }
}

