object Main {
  def isPerfect(n: Int): Boolean = {
    // نبدأ من 1 لأن القسمة على صفر غير ممكنة
    (1 until n).filter(n % _ == 0).sum == n
  }

  def main(args: Array[String]): Unit = {
    val limit = 10000
    // نطبع الأعداد المثالية حتى الحد
    (2 to limit).filter(isPerfect).foreach(println)
  }
}

object Main extends App {
  // تحويل كلمة إلى Pig Latin: ننقل الحرف الأول لنهاية الكلمة ونضيف "ay"
  def toPigLatin(word: String): String = {
    if (word.isEmpty) word
    else word.tail + word.head + "ay"
  }

  val sentence = "scala is fun"
  val translated = sentence.split(" ").map(toPigLatin).mkString(" ")
  println(s"Original: $sentence")
  println(s"Pig Latin: $translated")
}

object Main {
  def main(args: Array[String]): Unit = {
    val n = 30
    // المصفوفة تبدأ كلها true، ثم نُصفّي المضاعفات
    val isPrime = Array.fill(n + 1)(true)
    isPrime(0) = false
    isPrime(1) = false
    for (i <- 2 to math.sqrt(n).toInt if isPrime(i)) {
      for (j <- i * i to n by i) isPrime(j) = false
    }
    val primes = (2 to n).filter(isPrime)
    println(primes.mkString(", "))
  }
}

object Main {
  def qsort(list: List[Int]): List[Int] = list match {
    case Nil => Nil
    case pivot :: rest =>
      // تقسيم القائمة حول المحور ثم دمج النتائج
      val (less, greater) = rest.partition(_ < pivot)
      qsort(less) ::: pivot :: qsort(greater)
  }

  def main(args: Array[String]): Unit = {
    val nums = List(5, 2, 9, 1, 7, 3)
    println(qsort(nums).mkString(" "))
  }
}

