object Main extends App {
  // نتيجتنا ثابتة: حجر ضد ورقة => ورقة تفوز
  val player1 = "rock"
  val player2 = "paper"

  val result = (player1, player2) match {
    case ("rock", "paper")     => "Paper covers rock!"
    case ("paper", "scissors") => "Scissors cut paper!"
    case ("scissors", "rock")  => "Rock crushes scissors!"
    case (a, b) if a == b       => "Tie!"
    case _                      => "Invalid choice"
  }

  println(s"Player1: $player1, Player2: $player2")
  println(result)
}

